    "https://fonts.gstatic.com/s/roboto/v32/KFOmCnqEu92Fr1Me5WZLCzYlKw.ttf"
  );
}

function setup() {
  createCanvas((S = max(windowWidth, windowHeight)), S, WEBGL);
	describe("low poly sphere with random colored triangles");
  noFill();
  stroke("purple");
  noStroke();
  strokeWeight(2);
  loop();
  pts = genLowPolySphere(S / 3, ~~random(3,9), ~~random(1,11));
  if (fnt) textFont(fnt);
}

function draw() {
  background(0, 0, 8);
  orbitControl();
	lights();
	pointLight(255, 255, 255, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-width/2, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-height/2, 500);
	specularMaterial(255);
	shininess(75);
  drawSpherePts(pts);
  // // noLoop() removed for animation
}

function drawSpherePts(pts) {
  const il = pts.length;
  for (let i = 0; i < il - 1; i++) {
    const jl = pts[i].length;
    for (let j = 0; j <= jl; j++) {
      const k1 = i % 1 ? 0 : -1;
      const k2 = i % 1 ? 1 : 0;
      fill(
        noise(pts[i][j % jl].x) * 255,
        noise(pts[i][j % jl].y) * 255,
        noise(pts[i][j % jl].z) * 255,
        32
      );

      if (i === 0) {
        beginShape();
        vertex(pts[i][j % jl].x, pts[i][j % jl].y, pts[i][j % jl].z);
        vertex(
          pts[(i + 1) % il][j % jl].x,
          pts[(i + 1) % il][j % jl].y,
          pts[(i + 1) % il][j % jl].z
        );
        vertex(
          pts[(i + 1) % il][(j + 1) % jl].x,
          pts[(i + 1) % il][(j + 1) % jl].y,
          pts[(i + 1) % il][(j + 1) % jl].z
        );
        endShape(CLOSE);
      } else if (i === il - 2) {
        beginShape();
        vertex(pts[i][j % jl].x, pts[i][j % jl].y, pts[i][j % jl].z);
        vertex(
          pts[i][(j + 1) % jl].x,
          pts[i][(j + 1) % jl].y,
          pts[i][(j + 1) % jl].z
        );
        vertex(
          pts[(i + 1) % il][(j + 1) % jl].x,
          pts[(i + 1) % il][(j + 1) % jl].y,
          pts[(i + 1) % il][(j + 1) % jl].z
        );
        endShape(CLOSE);
      } else if (i % 2) {
        // 01 0
        beginShape();
        vertex(pts[i][j % jl].x, pts[i][j % jl].y, pts[i][j % jl].z);
        vertex(
          pts[i][(j + 1 + jl) % jl].x,
          pts[i][(j + 1 + jl) % jl].y,
          pts[i][(j + 1 + jl) % jl].z
        );
        vertex(
          pts[(i + 1) % il][(j + jl) % jl].x,
          pts[(i + 1) % il][(j + jl) % jl].y,
          pts[(i + 1) % il][(j + jl) % jl].z
        );
        endShape(CLOSE);
        // 0 06 || 1 15
        beginShape();
        vertex(pts[i][j % jl].x, pts[i][j % jl].y, pts[i][j % jl].z);
        vertex(
          pts[(i + 1) % il][(j - 1 + jl) % jl].x,
          pts[(i + 1) % il][(j - 1 + jl) % jl].y,
          pts[(i + 1) % il][(j - 1 + jl) % jl].z
        );
        vertex(
          pts[(i + 1) % il][(j + jl) % jl].x,
          pts[(i + 1) % il][(j + jl) % jl].y,
          pts[(i + 1) % il][(j + jl) % jl].z
        );
        endShape(CLOSE);
      } else {
        // 0 01
        beginShape();
        vertex(pts[i][j % jl].x, pts[i][j % jl].y, pts[i][j % jl].z);
        vertex(
          pts[(i + 1) % il][j % jl].x,
          pts[(i + 1) % il][j % jl].y,
          pts[(i + 1) % il][j % jl].z
        );
        vertex(
          pts[(i + 1) % il][(j + 1 + jl) % jl].x,
          pts[(i + 1) % il][(j + 1 + jl) % jl].y,
          pts[(i + 1) % il][(j + 1 + jl) % jl].z
        );
        endShape(CLOSE);
        // 01 1
        beginShape();
        vertex(pts[i][j % jl].x, pts[i][j % jl].y, pts[i][j % jl].z);
        vertex(
          pts[i][(j + 1 + jl) % jl].x,
          pts[i][(j + 1 + jl) % jl].y,
          pts[i][(j + 1 + jl) % jl].z
        );
        vertex(
          pts[(i + 1) % il][(j + 1 + jl) % jl].x,
          pts[(i + 1) % il][(j + 1 + jl) % jl].y,
          pts[(i + 1) % il][(j + 1 + jl) % jl].z
        );
        endShape(CLOSE);
      }
    }
  }
  // debug
  if (false) {
    push();
    noStroke();
    fill("cyan");
    for (let i = 1; i < il - 1; i++) {
      var jl = pts[i].length;
      for (let j = 0; j < jl; j++) {
        push();
        translate(pts[i][j].x, pts[i][j].y, pts[i][j].z);
        text("" + j, 0, 0);
        pop();
      }
    }
    pop();
  }
}

function genLowPolySphere(r, rn = 3, hn = 2) {
  var pts = [];
  for (let i = 0; i < hn + 2; i++) {
    pts[i] = [];
  }
  for (let i = 0; i < rn; i++) {
    pts[0][i] = { x: 0, y: -r, z: 0 };
    pts[hn + 1][i] = { x: 0, y: r, z: 0 };
  }

  const hd = (2 * r) / (hn + 1);
  const rda = TWO_PI / rn;
  for (let h = -r + hd, i = 0; h < r; h += hd, i++) {
    for (let ra = 0; ra < TWO_PI; ra += rda) {
      const w = sqrt(r * r - h * h);
      const raa = ra + random(-rda / 8, rda / 8) + ((i % 2) * rda) / 2;
      const rx = abs(w) * cos(raa);
      const rz = abs(w) * sin(raa);
      pts[i + 1].push({ x: rx, y: h, z: rz });
    }
  }

  return pts;
}

